def get_file_report(file_hash, include_raw=None, force_refresh=None, **_extra):
    import json, os, datetime, re, time, random, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_file_report"

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_key(dt):
        return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d")

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _new_id(prefix):
        now = _utcnow().strftime("%Y%m%d%H%M%S")
        rnd = hashlib.sha256(f"{prefix}|{time.time_ns()}|{random.random()}".encode("utf-8")).hexdigest()[:18]
        return f"vtc_{prefix}_{now}_{rnd}"

    def _log_request(client_id, status, error_code=None, credential=None, upstream_requests=0, relationship_pages=0):
        logs = _ensure_list(_load("request_logs.json"))
        now = _utcnow()
        rid = _new_id("req")
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "client_id": client_id,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(now),
            "day": _day_key(now),
            "upstream_requests": int(upstream_requests or 0),
            "relationship_pages": int(relationship_pages or 0),
        })
        _save("request_logs.json", logs)

    def _count_today(client_id, day, field):
        logs = _ensure_list(_load("request_logs.json"))
        total = 0
        for r in logs:
            if isinstance(r, dict) and r.get("client_id") == client_id and r.get("day") == day:
                try:
                    total += int(r.get(field) or 0)
                except Exception:
                    total += 0
        return total

    def _resolve_active_client():
        clients = _ensure_list(_load("api_clients.json"))
        # No explicit credential parameter for this tool: choose any active client that can serve calls.
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                # Must have quotas defined and non-negative
                try:
                    if int(c.get("daily_quota_requests", 0)) >= 0 and int(c.get("daily_quota_relationship_pages", 0)) >= 0:
                        return c
                except Exception:
                    continue
        return None

    def _enforce_quota(client_row, upstream_requests_to_add):
        now = _utcnow()
        day = _day_key(now)
        used = _count_today(client_row["id"], day, "upstream_requests")
        quota = client_row.get("daily_quota_requests", 0)
        try:
            quota = int(quota)
        except Exception:
            quota = 0
        if used + int(upstream_requests_to_add) > quota:
            return False, {"day": day, "used": used, "limit": quota, "attempted_add": int(upstream_requests_to_add)}
        return True, {"day": day, "used": used, "limit": quota}

    def _hash_kind(h):
        if not isinstance(h, str):
            return None
        hh = h.strip().lower()
        if re.fullmatch(r"[a-f0-9]{32}", hh):
            return "md5"
        if re.fullmatch(r"[a-f0-9]{40}", hh):
            return "sha1"
        if re.fullmatch(r"[a-f0-9]{64}", hh):
            return "sha256"
        return None

    # Validate inputs (relaxed: accept any valid hex hash; do not misinterpret 'sha1' literal)
    if not isinstance(file_hash, str) or not file_hash.strip():
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "file_hash must be a non-empty string", file_hash=file_hash)
    kind = _hash_kind(file_hash)
    if kind is None:
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "file_hash is not a valid MD5/SHA-1/SHA-256", file_hash=file_hash)

    if include_raw is None:
        include_raw = False
    if force_refresh is None:
        force_refresh = False
    if not isinstance(include_raw, bool):
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "include_raw must be boolean", include_raw=include_raw)
    if not isinstance(force_refresh, bool):
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "force_refresh must be boolean", force_refresh=force_refresh)

    client = _resolve_active_client()
    if not client:
        _log_request(None, "error", "UNAUTHORIZED", credential=None)
        return _err("UNAUTHORIZED", "No active client context available for this request")

    # Enforce active
    if client.get("status") != "active":
        _log_request(client.get("id"), "error", "UNAUTHORIZED", credential=client.get("id"))
        return _err("UNAUTHORIZED", "Client is not active", client_id=client.get("id"))

    now = _utcnow()

    # Upsert observable (unique(type,value))
    observables = _ensure_list(_load("observables.json"))
    canonical = file_hash.strip().lower()
    obs = None
    for o in observables:
        if isinstance(o, dict) and o.get("type") == "file" and o.get("value") == canonical:
            obs = o
            break
    if obs is None:
        obs = {
            "id": _new_id("obs"),
            "type": "file",
            "value": canonical,
            "file_hash_kind": kind,
            "url_normalization_version": None,
            "first_seen_at": _iso(now),
            "last_seen_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        observables.append(obs)
    else:
        # Enforce constraints
        if obs.get("file_hash_kind") is None:
            obs["file_hash_kind"] = kind
        obs["last_seen_at"] = _iso(now)
        obs["updated_at"] = _iso(now)
    _save("observables.json", observables)

    # Upsert report row (unique(client_id, observable_id, report_kind))
    reports = _ensure_list(_load("reports.json"))
    report_kind = "file_report"
    rpt = None
    for r in reports:
        if isinstance(r, dict) and r.get("client_id") == client["id"] and r.get("observable_id") == obs["id"] and r.get("report_kind") == report_kind:
            rpt = r
            break

    if rpt is None:
        rpt = {
            "id": _new_id("rpt"),
            "client_id": client["id"],
            "observable_id": obs["id"],
            "report_kind": report_kind,
            "vt_object_id": canonical,
            "status": "stale",
            "source_updated_at": None,
            "expires_at": None,
            "summary": {},
            "relationship_summaries": None,
            "raw_vt_payload": None,
            "last_fetched_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reports.append(rpt)

    # Determine if refresh required
    expires_at = _parse_dt(rpt.get("expires_at"))
    last_fetched = _parse_dt(rpt.get("last_fetched_at"))
    needs_fetch = bool(force_refresh) or (rpt.get("status") in ("stale", "error")) or (expires_at is not None and expires_at <= now) or (last_fetched is None)

    upstream_used = 0
    if needs_fetch:
        ok, qinfo = _enforce_quota(client, 1)
        if not ok:
            _log_request(client["id"], "error", "QUOTA_EXCEEDED", credential=client.get("id"))
            return _err("QUOTA_EXCEEDED", "Daily upstream request quota exceeded", client_id=client["id"], **qinfo)

        # Transition to fetching
        cur_status = rpt.get("status")
        allowed = {
            "fresh": {"stale", "fetching", "error"},
            "stale": {"fetching", "error", "fresh"},
            "fetching": {"fresh", "error"},
            "error": {"fetching", "stale"},
        }
        if cur_status not in allowed or "fetching" not in allowed[cur_status]:
            _log_request(client["id"], "error", "INVALID_TRANSITION", credential=client.get("id"))
            return _err("INVALID_TRANSITION", "Illegal report status transition", from_status=cur_status, to_status="fetching", report_id=rpt.get("id"))
        rpt["status"] = "fetching"
        rpt["updated_at"] = _iso(now)
        _save("reports.json", reports)

        # Offline "upstream" synthesis: update cache as if fetched.
        upstream_used = 1
        fetched_at = _utcnow()
        # Cache policy: 24h for public, 6h for premium, 1h for enterprise (arbitrary but consistent)
        tier = client.get("key_tier")
        ttl_hours = 24
        if tier == "premium":
            ttl_hours = 6
        elif tier == "enterprise":
            ttl_hours = 1
        exp = fetched_at + datetime.timedelta(hours=ttl_hours)

        detections = int(hashlib.sha256(canonical.encode("utf-8")).hexdigest()[:2], 16) % 71
        harmless = max(0, 90 - detections)
        suspicious = int(hashlib.sha256(("s" + canonical).encode("utf-8")).hexdigest()[:2], 16) % 10

        summary = {
            "hash": canonical,
            "hash_type": kind,
            "stats": {"malicious": detections, "suspicious": suspicious, "harmless": harmless, "undetected": max(0, 100 - detections - suspicious - harmless)},
            "reputation": (int(hashlib.sha256(("rep" + canonical).encode("utf-8")).hexdigest()[:2], 16) % 201) - 100,
            "last_analysis_date": _iso(fetched_at),
        }
        relationship_summaries = {
            "communicating_files": {"count": int(hashlib.sha256(("cf" + canonical).encode("utf-8")).hexdigest()[:2], 16) % 200},
            "contacted_domains": {"count": int(hashlib.sha256(("cd" + canonical).encode("utf-8")).hexdigest()[:2], 16) % 200},
            "contacted_ips": {"count": int(hashlib.sha256(("ci" + canonical).encode("utf-8")).hexdigest()[:2], 16) % 200},
            "downloaded_files": {"count": int(hashlib.sha256(("df" + canonical).encode("utf-8")).hexdigest()[:2], 16) % 200},
        }
        raw = {
            "data": {
                "type": "file",
                "id": canonical,
                "attributes": {
                    "last_analysis_stats": summary["stats"],
                    "reputation": summary["reputation"],
                    "last_analysis_date": summary["last_analysis_date"],
                },
            }
        }

        # Transition fetching -> fresh
        cur_status = rpt.get("status")
        if cur_status not in allowed or "fresh" not in allowed[cur_status]:
            _log_request(client["id"], "error", "INVALID_TRANSITION", credential=client.get("id"), upstream_requests=upstream_used)
            return _err("INVALID_TRANSITION", "Illegal report status transition", from_status=cur_status, to_status="fresh", report_id=rpt.get("id"))

        rpt["summary"] = summary
        rpt["relationship_summaries"] = relationship_summaries
        rpt["raw_vt_payload"] = raw
        rpt["last_fetched_at"] = _iso(fetched_at)
        rpt["expires_at"] = _iso(exp)
        rpt["status"] = "fresh"
        rpt["updated_at"] = _iso(fetched_at)
        rpt["vt_object_id"] = canonical
        _save("reports.json", reports)

    # Build response from stored row
    out = {
        "report": {
            "id": rpt.get("id"),
            "client_id": rpt.get("client_id"),
            "observable_id": rpt.get("observable_id"),
            "report_kind": rpt.get("report_kind"),
            "vt_object_id": rpt.get("vt_object_id"),
            "status": rpt.get("status"),
            "last_fetched_at": rpt.get("last_fetched_at"),
            "expires_at": rpt.get("expires_at"),
            "source_updated_at": rpt.get("source_updated_at"),
            "summary": rpt.get("summary") if isinstance(rpt.get("summary"), dict) else {},
            "relationship_summaries": rpt.get("relationship_summaries"),
        }
    }
    if include_raw:
        out["report"]["raw_vt_payload"] = rpt.get("raw_vt_payload")

    _log_request(client["id"], "ok", None, credential=client.get("id"), upstream_requests=upstream_used)
    return out

def get_url_report(url, include_raw=None, force_refresh=None, **_extra):
    import json, os, datetime, re, hashlib, time, urllib.parse, ipaddress

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    utc_day = now.date().isoformat()

    def _load_usage():
        return _load("usage_log.json")

    def _save_usage(rows):
        _save("usage_log.json", rows)

    def _count_usage(rows, client_id, day, kind):
        return sum(1 for r in rows if r.get("client_id") == client_id and r.get("utc_day") == day and r.get("kind") == kind and r.get("status") == "success")

    def _log_call(rows, client_id, endpoint, status, kind=None, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        rows.append({
            "id": "ul_" + hashlib.sha256(f"{client_id}|{endpoint}|{now_iso}|{len(rows)}".encode("utf-8")).hexdigest()[:24],
            "client_id": client_id,
            "endpoint": endpoint,
            "kind": kind,
            "status": status,
            "detail": detail,
            "utc_day": utc_day,
            "ts": now_iso,
            "latency_ms": latency_ms
        })

    clients = _load("api_clients.json")
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        usage = _load_usage()
        _log_call(usage, None, "get_url_report", "error", kind="read", detail="no_active_client")
        _save_usage(usage)
        return _err("UNAUTHORIZED", "No active API client context available.")
    client = active_clients[0]
    client_id = client.get("id")

    if not isinstance(url, str) or len(url.strip()) < 1:
        usage = _load_usage()
        _log_call(usage, client_id, "get_url_report", "error", kind="read", detail="url_invalid")
        _save_usage(usage)
        return _err("VALIDATION_ERROR", "url must be a non-empty string.")
    if include_raw is None:
        include_raw = False
    if force_refresh is None:
        force_refresh = False
    if not isinstance(include_raw, bool):
        usage = _load_usage()
        _log_call(usage, client_id, "get_url_report", "error", kind="read", detail="include_raw_type")
        _save_usage(usage)
        return _err("VALIDATION_ERROR", "include_raw must be a boolean.")
    if not isinstance(force_refresh, bool):
        usage = _load_usage()
        _log_call(usage, client_id, "get_url_report", "error", kind="read", detail="force_refresh_type")
        _save_usage(usage)
        return _err("VALIDATION_ERROR", "force_refresh must be a boolean.")

    def _normalize_url(u):
        u = u.strip()
        if "://" not in u:
            u = "http://" + u
        p = urllib.parse.urlsplit(u)
        scheme = (p.scheme or "http").lower()
        netloc = p.netloc
        if not netloc and p.path:
            # handle urls like http://example.com without netloc (rare)
            netloc = p.path
            path = ""
        else:
            path = p.path or "/"
        # userinfo removal not supported; keep if present but normalize host/port
        host = netloc
        userinfo = ""
        port = ""
        if "@" in host:
            userinfo, host = host.rsplit("@", 1)
        if host.startswith("["):
            # IPv6 in brackets
            m = re.match(r"^\[([0-9a-fA-F:]+)\](?::(\d+))?$", host)
            if m:
                host_only = m.group(1)
                port = m.group(2) or ""
                try:
                    host_norm = str(ipaddress.ip_address(host_only))
                except Exception:
                    host_norm = host_only.lower()
                host = f"[{host_norm}]"
        else:
            if ":" in host:
                host_only, port = host.rsplit(":", 1)
                if port and not port.isdigit():
                    host_only = host  # treat as part of hostname
                    port = ""
                host = host_only
            host = host.lower()
        # punycode for domains if needed
        try:
            if host and not host.startswith("["):
                host = host.encode("idna").decode("ascii")
        except Exception:
            pass
        norm_netloc = ""
        if userinfo:
            norm_netloc += userinfo + "@"
        norm_netloc += host
        if port:
            norm_netloc += ":" + port
        query = p.query
        fragment = ""  # drop fragments
        norm = urllib.parse.urlunsplit((scheme, norm_netloc, path or "/", query, fragment))
        return norm

    norm_url = _normalize_url(url)
    url_norm_version = 1
    vt_object_id = hashlib.sha256(norm_url.encode("utf-8")).hexdigest()  # url_id style

    observables = _load("observables.json")
    reports = _load("reports.json")
    usage = _load_usage()

    def _check_and_reserve_vt_request():
        used = _count_usage(usage, client_id, utc_day, "vt_request")
        limit = client.get("daily_quota_requests")
        if not isinstance(limit, int) or limit < 0:
            return _err("VALIDATION_ERROR", "Client daily_quota_requests is misconfigured.")
        if used + 1 > limit:
            return _err("QUOTA_EXCEEDED", "Daily upstream request quota exceeded.", limit=limit, used=used)
        return None

    # upsert observable
    obs = None
    for o in observables:
        if isinstance(o, dict) and o.get("type") == "url" and o.get("value") == norm_url:
            obs = o
            break
    if obs is None:
        obs_id = "obs_" + hashlib.sha256(f"url|{norm_url}".encode("utf-8")).hexdigest()[:24]
        obs = {
            "id": obs_id,
            "type": "url",
            "value": norm_url,
            "file_hash_kind": None,
            "url_normalization_version": url_norm_version,
            "first_seen_at": now_iso,
            "last_seen_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        observables.append(obs)
        _save("observables.json", observables)
    else:
        obs["url_normalization_version"] = url_norm_version
        if not obs.get("first_seen_at"):
            obs["first_seen_at"] = now_iso
        obs["last_seen_at"] = now_iso
        obs["updated_at"] = now_iso
        _save("observables.json", observables)

    # upsert report row
    report_kind = "url_report"
    rep = None
    for r in reports:
        if isinstance(r, dict) and r.get("client_id") == client_id and r.get("observable_id") == obs.get("id") and r.get("report_kind") == report_kind:
            rep = r
            break
    if rep is None:
        rep_id = "rep_" + hashlib.sha256(f"{client_id}|{obs.get('id')}|{report_kind}".encode("utf-8")).hexdigest()[:24]
        rep = {
            "id": rep_id,
            "client_id": client_id,
            "observable_id": obs.get("id"),
            "report_kind": report_kind,
            "vt_object_id": vt_object_id,
            "status": "stale",
            "source_updated_at": None,
            "expires_at": None,
            "summary": {},
            "relationship_summaries": None,
            "raw_vt_payload": None,
            "last_fetched_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        reports.append(rep)
        _save("reports.json", reports)

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    expires_dt = _parse_iso(rep.get("expires_at"))
    needs_fetch = force_refresh or (rep.get("status") in ("stale", "error")) or (rep.get("last_fetched_at") is None) or (expires_dt is not None and expires_dt <= now)

    _log_call(usage, client_id, "get_url_report", "success", kind="read", detail="cache_check")

    if needs_fetch:
        quota_err = _check_and_reserve_vt_request()
        if quota_err:
            _log_call(usage, client_id, "get_url_report", "error", kind="vt_request", detail="quota_exceeded")
            _save_usage(usage)
            return quota_err

        allowed = {"fresh": {"stale", "fetching", "error"}, "stale": {"fetching", "error", "fresh"}, "fetching": {"fresh", "error"}, "error": {"fetching", "stale"}}
        cur = rep.get("status")
        if cur not in allowed or "fetching" not in allowed[cur]:
            _log_call(usage, client_id, "get_url_report", "error", kind="vt_request", detail="invalid_transition_to_fetching")
            _save_usage(usage)
            return _err("INVALID_TRANSITION", f"Cannot transition report status from {cur} to fetching.")
        rep["status"] = "fetching"
        rep["updated_at"] = now_iso
        _save("reports.json", reports)

        h = hashlib.sha256(f"vt|url|{norm_url}".encode("utf-8")).hexdigest()
        malicious = int(h[:2], 16) % 20
        suspicious = int(h[2:4], 16) % 8
        harmless = 60 + (int(h[4:6], 16) % 30)
        undetected = max(0, 90 - malicious - suspicious)
        rep["summary"] = {
            "observable_type": "url",
            "url": norm_url,
            "url_id": vt_object_id,
            "stats": {"malicious": malicious, "suspicious": suspicious, "harmless": harmless, "undetected": undetected},
            "reputation": (int(h[6:8], 16) % 201) - 100,
            "last_analysis_date": now_iso,
        }
        rep["relationship_summaries"] = {
            "communicating_files": {"count_estimate": int(h[8:10], 16) % 5000},
            "contacted_domains": {"count_estimate": int(h[10:12], 16) % 5000},
            "contacted_ips": {"count_estimate": int(h[12:14], 16) % 5000},
            "downloaded_files": {"count_estimate": int(h[14:16], 16) % 5000},
            "redirecting_urls": {"count_estimate": int(h[16:18], 16) % 1000},
            "redirected_urls": {"count_estimate": int(h[18:20], 16) % 1000},
            "related_threat_actors": {"count_estimate": int(h[20:22], 16) % 200},
        }
        if include_raw:
            rep["raw_vt_payload"] = {
                "data": {
                    "type": "url",
                    "id": vt_object_id,
                    "attributes": {
                        "url": norm_url,
                        "last_analysis_stats": rep["summary"]["stats"],
                        "reputation": rep["summary"]["reputation"],
                    }
                },
