def get_domain_report(domain, include_raw=None, force_refresh=None, **_extra):
    import json, os, datetime, re, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    utc_day = now.date().isoformat()

    def _load_usage():
        return _load("usage_log.json")

    def _save_usage(rows):
        _save("usage_log.json", rows)

    def _count_usage(rows, client_id, day, kind):
        return sum(1 for r in rows if r.get("client_id") == client_id and r.get("utc_day") == day and r.get("kind") == kind and r.get("status") == "success")

    def _log_call(rows, client_id, endpoint, status, kind=None, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        rows.append({
            "id": "ul_" + hashlib.sha256(f"{client_id}|{endpoint}|{now_iso}|{len(rows)}".encode("utf-8")).hexdigest()[:24],
            "client_id": client_id,
            "endpoint": endpoint,
            "kind": kind,
            "status": status,
            "detail": detail,
            "utc_day": utc_day,
            "ts": now_iso,
            "latency_ms": latency_ms
        })

    clients = _load("api_clients.json")
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        usage = _load_usage()
        _log_call(usage, None, "get_domain_report", "error", kind="read", detail="no_active_client")
        _save_usage(usage)
        return _err("UNAUTHORIZED", "No active API client context available.")
    client = active_clients[0]
    client_id = client.get("id")

    if not isinstance(domain, str) or len(domain.strip()) < 1:
        usage = _load_usage()
        _log_call(usage, client_id, "get_domain_report", "error", kind="read", detail="domain_invalid")
        _save_usage(usage)
        return _err("VALIDATION_ERROR", "domain must be a non-empty string.")
    if include_raw is None:
        include_raw = False
    if force_refresh is None:
        force_refresh = False
    if not isinstance(include_raw, bool):
        usage = _load_usage()
        _log_call(usage, client_id, "get_domain_report", "error", kind="read", detail="include_raw_type")
        _save_usage(usage)
        return _err("VALIDATION_ERROR", "include_raw must be a boolean.")
    if not isinstance(force_refresh, bool):
        usage = _load_usage()
        _log_call(usage, client_id, "get_domain_report", "error", kind="read", detail="force_refresh_type")
        _save_usage(usage)
        return _err("VALIDATION_ERROR", "force_refresh must be a boolean.")

    d = domain.strip().rstrip(".").lower()
    # basic sanity (not full RFC)
    if len(d) > 253 or any(len(lbl) == 0 for lbl in d.split(".")):
        usage = _load_usage()
        _log_call(usage, client_id, "get_domain_report", "error", kind="read", detail="domain_format")
        _save_usage(usage)
        return _err("VALIDATION_ERROR", "domain is not a valid domain name.")
    try:
        d = d.encode("idna").decode("ascii")
    except Exception:
        pass

    observables = _load("observables.json")
    reports = _load("reports.json")
    usage = _load_usage()

    def _check_and_reserve_vt_request():
        used = _count_usage(usage, client_id, utc_day, "vt_request")
        limit = client.get("daily_quota_requests")
        if not isinstance(limit, int) or limit < 0:
            return _err("VALIDATION_ERROR", "Client daily_quota_requests is misconfigured.")
        if used + 1 > limit:
            return _err("QUOTA_EXCEEDED", "Daily upstream request quota exceeded.", limit=limit, used=used)
        return None

    obs = None
    for o in observables:
        if isinstance(o, dict) and o.get("type") == "domain" and o.get("value") == d:
            obs = o
            break
    if obs is None:
        obs_id = "obs_" + hashlib.sha256(f"domain|{d}".encode("utf-8")).hexdigest()[:24]
        obs = {
            "id": obs_id,
            "type": "domain",
            "value": d,
            "file_hash_kind": None,
            "url_normalization_version": None,
            "first_seen_at": now_iso,
            "last_seen_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        observables.append(obs)
        _save("observables.json", observables)
    else:
        if not obs.get("first_seen_at"):
            obs["first_seen_at"] = now_iso
        obs["last_seen_at"] = now_iso
        obs["updated_at"] = now_iso
        _save("observables.json", observables)

    report_kind = "domain_report"
    rep = None
    for r in reports:
        if isinstance(r, dict) and r.get("client_id") == client_id and r.get("observable_id") == obs.get("id") and r.get("report_kind") == report_kind:
            rep = r
            break
    if rep is None:
        rep_id = "rep_" + hashlib.sha256(f"{client_id}|{obs.get('id')}|{report_kind}".encode("utf-8")).hexdigest()[:24]
        rep = {
            "id": rep_id,
            "client_id": client_id,
            "observable_id": obs.get("id"),
            "report_kind": report_kind,
            "vt_object_id": d,
            "status": "stale",
            "source_updated_at": None,
            "expires_at": None,
            "summary": {},
            "relationship_summaries": None,
            "raw_vt_payload": None,
            "last_fetched_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        reports.append(rep)
        _save("reports.json", reports)

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    expires_dt = _parse_iso(rep.get("expires_at"))
    needs_fetch = force_refresh or (rep.get("status") in ("stale", "error")) or (rep.get("last_fetched_at") is None) or (expires_dt is not None and expires_dt <= now)

    _log_call(usage, client_id, "get_domain_report", "success", kind="read", detail="cache_check")

    if needs_fetch:
        quota_err = _check_and_reserve_vt_request()
        if quota_err:
            _log_call(usage, client_id, "get_domain_report", "error", kind="vt_request", detail="quota_exceeded")
            _save_usage(usage)
            return quota_err

        allowed = {"fresh": {"stale", "fetching", "error"}, "stale": {"fetching", "error", "fresh"}, "fetching": {"fresh", "error"}, "error": {"fetching", "stale"}}
        cur = rep.get("status")
        if cur not in allowed or "fetching" not in allowed[cur]:
            _log_call(usage, client_id, "get_domain_report", "error", kind="vt_request", detail="invalid_transition_to_fetching")
            _save_usage(usage)
            return _err("INVALID_TRANSITION", f"Cannot transition report status from {cur} to fetching.")
        rep["status"] = "fetching"
        rep["updated_at"] = now_iso
        _save("reports.json", reports)

        h = hashlib.sha256(f"vt|domain|{d}".encode("utf-8")).hexdigest()
        rep["summary"] = {
            "observable_type": "domain",
            "domain": d,
            "reputation": (int(h[:2], 16) % 201) - 100,
            "categories": [],
            "whois_excerpt": None,
            "dns_excerpt": None,
            "last_analysis_date": now_iso,
        }
        rep["relationship_summaries"] = {
            "historical_ssl_certificates": {"count_estimate": int(h[2:4], 16) % 5000},
            "subdomains": {"count_estimate": int(h[4:6], 16) % 50000},
            "resolutions": {"count_estimate": int(h[6:8], 16) % 50000},
            "historical_whois": {"count_estimate": int(h[8:10], 16) % 5000},
            "historical_urls": {"count_estimate": int(h[10:12], 16) % 50000},
            "related_threat_actors": {"count_estimate": int(h[12:14], 16) % 200},
        }
        if include_raw:
            rep["raw_vt_payload"] = {
                "data": {
                    "type": "domain",
                    "id": d,
                    "attributes": {
                        "reputation": rep["summary"]["reputation"],
                    }
                },
                "meta": {"simulated": True}
            }

        # cache policy: 12h for domain
        rep["vt_object_id"] = d
        rep["source_updated_at"] = now_iso
        rep["last_fetched_at"] = now_iso
        rep["expires_at"] = (now + datetime.timedelta(hours=12)).isoformat() + "Z"

        if rep.get("status") != "fetching":
            _log_call(usage, client_id, "get_domain_report", "error", kind="vt_request", detail="unexpected_status_not_fetching")
            _save_usage(usage)
            return _err("INVALID_TRANSITION", f"Unexpected report status {rep.get('status')} during fetch.")
        rep["status"] = "fresh"
        rep["updated_at"] = now_iso
        _save("reports.json", reports)

        _log_call(usage, client_id, "get_domain_report", "success", kind="vt_request", detail="fetched")

    _save_usage(usage)

    out = {
        "client_id": client_id,
        "observable": {"id": obs.get("id"), "type": obs.get("type"), "value": obs.get("value")},
        "report": {k: v for k, v in rep.items() if k != "raw_vt_payload"},
        "cached": not needs_fetch
    }
    if include_raw:
        out["report"]["raw_vt_payload"] = rep.get("raw_vt_payload")
    return out

