def get_file_behavior_summary(file_hash, include_raw=None, force_refresh=None, **_extra):
    import json, os, datetime, re, time, random, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_file_behavior_summary"

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_key(dt):
        return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d")

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _new_id(prefix):
        now = _utcnow().strftime("%Y%m%d%H%M%S")
        rnd = hashlib.sha256(f"{prefix}|{time.time_ns()}|{random.random()}".encode("utf-8")).hexdigest()[:18]
        return f"vtc_{prefix}_{now}_{rnd}"

    def _log_request(client_id, status, error_code=None, credential=None, upstream_requests=0, relationship_pages=0):
        logs = _ensure_list(_load("request_logs.json"))
        now = _utcnow()
        rid = _new_id("req")
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "client_id": client_id,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(now),
            "day": _day_key(now),
            "upstream_requests": int(upstream_requests or 0),
            "relationship_pages": int(relationship_pages or 0),
        })
        _save("request_logs.json", logs)

    def _count_today(client_id, day, field):
        logs = _ensure_list(_load("request_logs.json"))
        total = 0
        for r in logs:
            if isinstance(r, dict) and r.get("client_id") == client_id and r.get("day") == day:
                try:
                    total += int(r.get(field) or 0)
                except Exception:
                    total += 0
        return total

    def _resolve_active_client():
        clients = _ensure_list(_load("api_clients.json"))
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                try:
                    if int(c.get("daily_quota_requests", 0)) >= 0 and int(c.get("daily_quota_relationship_pages", 0)) >= 0:
                        return c
                except Exception:
                    continue
        return None

    def _enforce_quota(client_row, upstream_requests_to_add):
        now = _utcnow()
        day = _day_key(now)
        used = _count_today(client_row["id"], day, "upstream_requests")
        quota = client_row.get("daily_quota_requests", 0)
        try:
            quota = int(quota)
        except Exception:
            quota = 0
        if used + int(upstream_requests_to_add) > quota:
            return False, {"day": day, "used": used, "limit": quota, "attempted_add": int(upstream_requests_to_add)}
        return True, {"day": day, "used": used, "limit": quota}

    def _hash_kind(h):
        if not isinstance(h, str):
            return None
        hh = h.strip().lower()
        if re.fullmatch(r"[a-f0-9]{32}", hh):
            return "md5"
        if re.fullmatch(r"[a-f0-9]{40}", hh):
            return "sha1"
        if re.fullmatch(r"[a-f0-9]{64}", hh):
            return "sha256"
        return None

    if not isinstance(file_hash, str) or not file_hash.strip():
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "file_hash must be a non-empty string", file_hash=file_hash)
    kind = _hash_kind(file_hash)
    if kind is None:
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "file_hash is not a valid MD5/SHA-1/SHA-256", file_hash=file_hash)

    if include_raw is None:
        include_raw = False
    if force_refresh is None:
        force_refresh = False
    if not isinstance(include_raw, bool):
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "include_raw must be boolean", include_raw=include_raw)
    if not isinstance(force_refresh, bool):
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "force_refresh must be boolean", force_refresh=force_refresh)

    client = _resolve_active_client()
    if not client:
        _log_request(None, "error", "UNAUTHORIZED", credential=None)
        return _err("UNAUTHORIZED", "No active client context available for this request")

    if client.get("status") != "active":
        _log_request(client.get("id"), "error", "UNAUTHORIZED", credential=client.get("id"))
        return _err("UNAUTHORIZED", "Client is not active", client_id=client.get("id"))

    now = _utcnow()

    # Upsert observable
    observables = _ensure_list(_load("observables.json"))
    canonical = file_hash.strip().lower()
    obs = None
    for o in observables:
        if isinstance(o, dict) and o.get("type") == "file" and o.get("value") == canonical:
            obs = o
            break
    if obs is None:
        obs = {
            "id": _new_id("obs"),
            "type": "file",
            "value": canonical,
            "file_hash_kind": kind,
            "url_normalization_version": None,
            "first_seen_at": _iso(now),
            "last_seen_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        observables.append(obs)
    else:
        if obs.get("file_hash_kind") is None:
            obs["file_hash_kind"] = kind
        obs["last_seen_at"] = _iso(now)
        obs["updated_at"] = _iso(now)
    _save("observables.json", observables)

    # Upsert report row
    reports = _ensure_list(_load("reports.json"))
    report_kind = "file_behavior_summary"
    rpt = None
    for r in reports:
        if isinstance(r, dict) and r.get("client_id") == client["id"] and r.get("observable_id") == obs["id"] and r.get("report_kind") == report_kind:
            rpt = r
            break
    if rpt is None:
        rpt = {
            "id": _new_id("rpt"),
            "client_id": client["id"],
            "observable_id": obs["id"],
            "report_kind": report_kind,
            "vt_object_id": canonical,
            "status": "stale",
            "source_updated_at": None,
            "expires_at": None,
            "summary": {},
            "relationship_summaries": None,
            "raw_vt_payload": None,
            "last_fetched_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reports.append(rpt)

    expires_at = _parse_dt(rpt.get("expires_at"))
    last_fetched = _parse_dt(rpt.get("last_fetched_at"))
    needs_fetch = bool(force_refresh) or (rpt.get("status") in ("stale", "error")) or (expires_at is not None and expires_at <= now) or (last_fetched is None)

    upstream_used = 0
    if needs_fetch:
        ok, qinfo = _enforce_quota(client, 1)
        if not ok:
            _log_request(client["id"], "error", "QUOTA_EXCEEDED", credential=client.get("id"))
            return _err("QUOTA_EXCEEDED", "Daily upstream request quota exceeded", client_id=client["id"], **qinfo)

        allowed = {
            "fresh": {"stale", "fetching", "error"},
            "stale": {"fetching", "error", "fresh"},
            "fetching": {"fresh", "error"},
            "error": {"fetching", "stale"},
        }
        cur_status = rpt.get("status")
        if cur_status not in allowed or "fetching" not in allowed[cur_status]:
            _log_request(client["id"], "error", "INVALID_TRANSITION", credential=client.get("id"))
            return _err("INVALID_TRANSITION", "Illegal report status transition", from_status=cur_status, to_status="fetching", report_id=rpt.get("id"))

        rpt["status"] = "fetching"
        rpt["updated_at"] = _iso(now)
        _save("reports.json", reports)

        upstream_used = 1
        fetched_at = _utcnow()
        tier = client.get("key_tier")
        ttl_hours = 24
        if tier == "premium":
            ttl_hours = 6
        elif tier == "enterprise":
            ttl_hours = 1
        exp = fetched_at + datetime.timedelta(hours=ttl_hours)

        # Deterministic synthesized "behavior" summary
        seed = hashlib.sha256(("beh|" + canonical).encode("utf-8")).hexdigest()
        processes = (int(seed[0:2], 16) % 40) + 1
        files_written = int(seed[2:4], 16) % 300
        reg_keys = int(seed[4:6], 16) % 200
        dns_queries = int(seed[6:8], 16) % 500
        http_requests = int(seed[8:10], 16) % 400
        severity = ["low", "medium", "high"][int(seed[10:12], 16) % 3]

        summary = {
            "hash": canonical,
            "hash_type": kind,
            "severity": severity,
            "sandbox": {
                "processes": processes,
                "files_written": files_written,
                "registry_keys_touched": reg_keys,
                "dns_queries": dns_queries,
                "http_requests": http_requests,
            },
            "last_behavior_date": _iso(fetched_at),
        }
        raw = {
            "data": {
                "type": "file_behavior",
                "id": canonical,
                "attributes": {
                    "processes": processes,
                    "files_written": files_written,
                    "registry_keys_touched": reg_keys,
                    "dns_queries": dns_queries,
                    "http_requests": http_requests,
                    "severity": severity,
                },
            }
        }

        cur_status = rpt.get("status")
        if cur_status not in allowed or "fresh" not in allowed[cur_status]:
            _log_request(client["id"], "error", "INVALID_TRANSITION", credential=client.get("id"), upstream_requests=upstream_used)
            return _err("INVALID_TRANSITION", "Illegal report status transition", from_status=cur_status, to_status="fresh", report_id=rpt.get("id"))

        rpt["summary"] = summary
        rpt["relationship_summaries"] = None
        rpt["raw_vt_payload"] = raw
        rpt["last_fetched_at"] = _iso(fetched_at)
        rpt["expires_at"] = _iso(exp)
        rpt["status"] = "fresh"
        rpt["updated_at"] = _iso(fetched_at)
        rpt["vt_object_id"] = canonical
        _save("reports.json", reports)

    out = {
        "report": {
            "id": rpt.get("id"),
            "client_id": rpt.get("client_id"),
            "observable_id": rpt.get("observable_id"),
            "report_kind": rpt.get("report_kind"),
            "vt_object_id": rpt.get("vt_object_id"),
            "status": rpt.get("status"),
            "last_fetched_at": rpt.get("last_fetched_at"),
            "expires_at": rpt.get("expires_at"),
            "summary": rpt.get("summary") if isinstance(rpt.get("summary"), dict) else {},
        }
    }
    if include_raw:
        out["report"]["raw_vt_payload"] = rpt.get("raw_vt_payload")

    _log_request(client["id"], "ok", None, credential=client.get("id"), upstream_requests=upstream_used)
    return out

def get_file_relationship(file_hash, relationship_type, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, random, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_file_relationship"

    REL_ENUM = [
        "communicating_files", "contacted_domains", "contacted_ips", "downloaded_files",
        "redirecting_urls", "redirected_urls", "related_threat_actors", "historical_ssl_certificates",
        "subdomains", "resolutions", "historical_whois", "historical_urls", "related_urls",
        "related_domains", "related_ips", "execution_parents", "dropped_files", "contacted_urls"
    ]

    # For "file" observable, all relationship_type values are allowed by schema for relationships.relationship_type.
    # The business rule says validate compatibility; VT supports many on files, and this server accepts all enumerated.
    FILE_COMPAT = set(REL_ENUM)

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _day_key(dt):
        return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _new_id(prefix):
        now = _utcnow().strftime("%Y%m%d%H%M%S")
        rnd = hashlib.sha256(f"{prefix}|{time.time_ns()}|{random.random()}".encode("utf-8")).hexdigest()[:18]
        return f"vtc_{prefix}_{now}_{rnd}"

    def _log_request(client_id, status, error_code=None, credential=None, upstream_requests=0, relationship_pages=0):
        logs = _ensure_list(_load("request_logs.json"))
        now = _utcnow()
        rid = _new_id("req")
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "client_id": client_id,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(now),
            "day": _day_key(now),
            "upstream_requests": int(upstream_requests or 0),
            "relationship_pages": int(relationship_pages or 0),
        })
        _save("request_logs.json", logs)

    def _count_today(client_id, day, field):
        logs = _ensure_list(_load("request_logs.json"))
        total = 0
        for r in logs:
            if isinstance(r, dict) and r.get("client_id") == client_id and r.get("day") == day:
                try:
                    total += int(r.get(field) or 0)
                except Exception:
                    total += 0
        return total

    def _resolve_active_client():
        clients = _ensure_list(_load("api_clients.json"))
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                try:
                    if int(c.get("daily_quota_requests", 0)) >= 0 and int(c.get("daily_quota_relationship_pages", 0)) >= 0:
                        return c
                except Exception:
                    continue
        return None

    def _enforce_request_quota(client_row, upstream_requests_to_add):
        now = _utcnow()
        day = _day_key(now)
        used = _count_today(client_row["id"], day, "upstream_requests")
        quota = client_row.get("daily_quota_requests", 0)
        try:
            quota = int(quota)
        except Exception:
            quota = 0
        if used + int(upstream_requests_to_add) > quota:
            return False, {"day": day, "used": used, "limit": quota, "attempted_add": int(upstream_requests_to_add)}
        return True, {"day": day, "used": used, "limit": quota}

    def _enforce_relationship_pages_quota(client_row, pages_to_add):
        now = _utcnow()
        day = _day_key(now)
        used = _count_today(client_row["id"], day, "relationship_pages")
        quota = client_row.get("daily_quota_relationship_pages", 0)
        try:
            quota = int(quota)
        except Exception:
            quota = 0
        if used + int(pages_to_add) > quota:
            return False, {"day": day, "used": used, "limit": quota, "attempted_add": int(pages_to_add)}
        return True, {"day": day, "used": used, "limit": quota}

    def _hash_kind(h):
        if not isinstance(h, str):
            return None
        hh = h.strip().lower()
        if re.fullmatch(r"[a-f0-9]{32}", hh):
            return "md5"
        if re.fullmatch(r"[a-f0-9]{40}", hh):
            return "sha1"
        if re.fullmatch(r"[a-f0-9]{64}", hh):
            return "sha256"
        return None

    def _cursor_obj(cur):
        if cur is None:
            return {"offset": 0}
        if not isinstance(cur, str) or not cur.strip():
            return None
        # Accept opaque VT-like base64 JSON cursors, but we only use them as cache keys; also decode offset if possible.
        try:
            raw = base64.b64decode(cur + "===")
            s = raw.decode("utf-8", errors="ignore")
            # Minimal extraction of offset for stable ordering
            m = re.search(r'"offset"\s*:\s*(\d+)', s)
            if m:
                return {"offset": int(m.group(1))}
            m = re.search(r'"page"\s*:\s*(\d+)', s)
            if m:
                # heuristic: page N => offset (N-1)*25
                p = int(m.group(1))
                return {"offset": max(0, (p - 1) * 25)}
            return {"offset": 0}
        except Exception:
            # Cursor is opaque; still treat it as acceptable token
            return {"offset": 0}

    # Validate inputs
    if not isinstance(file_hash, str) or not file_hash.strip():
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "file_hash must be a non-empty string", file_hash=file_hash)
    kind = _hash_kind(file_hash)
    if kind is None:
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "file_hash is not a valid MD5/SHA-1/SHA-256", file_hash=file_hash)

    if relationship_type not in REL_ENUM:
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "relationship_type is invalid", relationship_type=relationship_type)

    if relationship_type not in FILE_COMPAT:
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "relationship_type is not compatible with file observables", relationship_type=relationship_type, observable_type="file")

    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "limit must be an integer", limit=limit)
    if limit < 1 or limit > 100:
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", limit=limit)

    cobj = _cursor_obj(cursor)
