        return _err("UNAUTHORIZED", "Client is not active", client_id=client.get("id"))

    now = _utcnow()
    canonical = file_hash.strip().lower()

    # Upsert from observable
    observables = _ensure_list(_load("observables.json"))
    from_obs = None
    for o in observables:
        if isinstance(o, dict) and o.get("type") == "file" and o.get("value") == canonical:
            from_obs = o
            break
    if from_obs is None:
        from_obs = {
            "id": _new_id("obs"),
            "type": "file",
            "value": canonical,
            "file_hash_kind": kind,
            "url_normalization_version": None,
            "first_seen_at": _iso(now),
            "last_seen_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        observables.append(from_obs)
    else:
        if from_obs.get("file_hash_kind") is None:
            from_obs["file_hash_kind"] = kind
        from_obs["last_seen_at"] = _iso(now)
        from_obs["updated_at"] = _iso(now)
    _save("observables.json", observables)

    relationships = _ensure_list(_load("relationships.json"))

    # Serve from cache if we have rows for this cursor+type; vt_cursor persisted per row.
    cur_token = cursor if cursor is not None else None
    cached = [
        r for r in relationships
        if isinstance(r, dict)
        and r.get("client_id") == client["id"]
        and r.get("from_observable_id") == from_obs["id"]
        and r.get("relationship_type") == relationship_type
