            elif relationship_type in ("redirecting_urls", "redirected_urls", "related_urls", "historical_urls", "contacted_urls"):
                url = f"http://example{int(h[2:6],16)%10000}.com/path/{int(h[6:10],16)%10000}"
                to_val = url
                to_obs = None
                for o in observables:
                    if isinstance(o, dict) and o.get("type") == "url" and o.get("value") == to_val:
                        to_obs = o
                        break
                if to_obs is None:
                    to_obs = {
                        "id": _new_id("obs"),
                        "type": "url",
                        "value": to_val,
                        "file_hash_kind": None,
                        "url_normalization_version": 1,
                        "first_seen_at": _iso(now),
                        "last_seen_at": _iso(now),
                        "created_at": _iso(now),
                        "updated_at": _iso(now),
                    }
                    observables.append(to_obs)
                else:
                    if to_obs.get("url_normalization_version") is None:
                        to_obs["url_normalization_version"] = 1
                    to_obs["last_seen_at"] = _iso(now)
                    to_obs["updated_at"] = _iso(now)
                to_obs_id = to_obs["id"]
                to_ext_type = "observable"
                to_disp = to_val
            elif relationship_type in ("communicating_files", "downloaded_files", "execution_parents", "dropped_files"):
                # related file as observable
                # generate pseudo sha256
                fh = hashlib.sha256(f"child|{canonical}|{relationship_type}|{h}".encode("utf-8")).hexdigest()
                to_val = fh
                to_obs = None
                for o in observables:
                    if isinstance(o, dict) and o.get("type") == "file" and o.get("value") == to_val:
                        to_obs = o
                        break
                if to_obs is None:
                    to_obs = {
                        "id": _new_id("obs"),
                        "type": "file",
                        "value": to_val,
                        "file_hash_kind": "sha256",
                        "url_normalization_version": None,
                        "first_seen_at": _iso(now),
                        "last_seen_at": _iso(now),
                        "created_at": _iso(now),
                        "updated_at": _iso(now),
                    }
                    observables.append(to_obs)
                else:
                    if to_obs.get("file_hash_kind") is None:
                        to_obs["file_hash_kind"] = "sha256"
                    to_obs["last_seen_at"] = _iso(now)
                    to_obs["updated_at"] = _iso(now)
                to_obs_id = to_obs["id"]
                to_ext_type = "observable"
                to_disp = to_val
            elif relationship_type in ("historical_ssl_certificates",):
                to_obs_id = None
                to_ext_type = "certificate"
                to_ext_id = ":".join([h[j:j+2] for j in range(0, 40, 2)])
                to_disp = f"cert-{to_ext_id[:8]}"
            elif relationship_type in ("historical_whois",):
                to_obs_id = None
                to_ext_type = "whois"
                to_ext_id = f"whois-{h[:12]}"
                to_disp = to_ext_id
            elif relationship_type in ("related_threat_actors",):
                to_obs_id = None
                to_ext_type = "threat_actor"
                to_ext_id = f"ta_{h[:10]}"
                to_disp = f"actor-{h[:6]}"
            else:
                # fallback
                if choose < 70:
                    to_obs_id = None
                    to_ext_type = "unknown"
                    to_ext_id = f"ext-{h[:16]}"
                    to_disp = to_ext_id
                else:
                    # map to domain observable
                    dom = f"example{int(h[2:6],16)%10000}.net"
                    to_val = dom.lower()
                    to_obs = None
                    for o in observables:
                        if isinstance(o, dict) and o.get("type") == "domain" and o.get("value") == to_val:
                            to_obs = o
                            break
                    if to_obs is None:
                        to_obs = {
                            "id": _new_id("obs"),
                            "type": "domain",
                            "value": to_val,
                            "file_hash_kind": None,
                            "url_normalization_version": None,
                            "first_seen_at": _iso(now),
                            "last_seen_at": _iso(now),
                            "created_at": _iso(now),
                            "updated_at": _iso(now),
                        }
                        observables.append(to_obs)
                    else:
                        to_obs["last_seen_at"] = _iso(now)
                        to_obs["updated_at"] = _iso(now)
                    to_obs_id = to_obs["id"]
                    to_ext_type = "observable"
                    to_disp = to_val

            # Enforce relationship constraints
            if to_obs_id is not None:
                to_ext_type = "observable"
                to_ext_id = None
            else:
                if to_ext_id is None:
                    to_ext_id = f"ext-{h[:16]}"
                if to_ext_type is None:
                    to_ext_type = "unknown"

            rel_row = {
                "id": _new_id("rel"),
                "client_id": client["id"],
                "from_observable_id": from_obs["id"],
                "relationship_type": relationship_type,
                "to_observable_id": to_obs_id,
                "to_external_type": to_ext_type,
                "to_external_id": to_ext_id,
                "to_display": to_disp,
                "vt_cursor": cur_token,
                "fetched_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }

            # unique constraint: avoid duplicates
            uniq_key = (rel_row["client_id"], rel_row["from_observable_id"], rel_row["relationship_type"], rel_row.get("to_observable_id") or "", rel_row.get("to_external_id") or "")
            exists = False
            for rr in relationships:
                if not isinstance(rr, dict):
                    continue
                k = (rr.get("client_id"), rr.get("from_observable_id"), rr.get("relationship_type"), rr.get("to_observable_id") or "", rr.get("to_external_id") or "")
                if k == uniq_key:
                    exists = True
                    break
            if not exists:
                relationships.append(rel_row)
                produced.append(rel_row)

        _save("observables.json", observables)
        _save("relationships.json", relationships)

        cached = [
            r for r in relationships
            if isinstance(r, dict)
            and r.get("client_id") == client["id"]
            and r.get("from_observable_id") == from_obs["id"]
            and r.get("relationship_type") == relationship_type
            and r.get("vt_cursor") == cur_token
        ]

    # Deterministic ordering for stable pagination
    cached_sorted = sorted(cached, key=lambda r: (r.get("to_display") or "", r.get("id") or ""))
    items = cached_sorted[:limit]

    # Compute next cursor: if we returned limit and underlying page_size suggests more, return a synthetic opaque cursor.
    has_more = len(cached_sorted) > limit
    next_cursor = None
    if has_more:
        # Keep same cursor namespace but advance offset heuristically.
        cur_offset = int(cobj.get("offset", 0) or 0)
        next_obj = {"offset": cur_offset + 25, "page": (cur_offset // 25) + 2}
        b = json.dumps(next_obj, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.b64encode(b).decode("utf-8").rstrip("=")

    resp_items = []
    for r in items:
        resp_items.append({
            "id": r.get("id"),
            "relationship_type": r.get("relationship_type"),
            "from_observable_id": r.get("from_observable_id"),
            "to_observable_id": r.get("to_observable_id"),
            "to_external_type": r.get("to_external_type"),
            "to_external_id": r.get("to_external_id"),
            "to_display": r.get("to_display"),
            "vt_cursor": r.get("vt_cursor"),
            "fetched_at": r.get("fetched_at"),
        })

    out = {
        "relationship_type": relationship_type,
        "from": {"type": "file", "value": canonical, "observable_id": from_obs["id"]},
        "items": resp_items,
        "meta": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": bool(next_cursor),
            "returned": len(resp_items),
            "cached": bool(upstream_used == 0),
        }
    }

    _log_request(client["id"], "ok", None, credential=client.get("id"), upstream_requests=upstream_used, relationship_pages=page_used)
    return out

def get_url_relationship(url, relationship_type, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, re
    import urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_url_relationship"
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    day = now.strftime("%Y-%m-%d")

    if not isinstance(url, str) or len(url.strip()) < 1:
        return _err("VALIDATION_ERROR", "url must be a non-empty string")
    rel_enum = {
        "communicating_files","contacted_domains","contacted_ips","downloaded_files",
        "redirecting_urls","redirected_urls","related_threat_actors","historical_ssl_certificates",
        "subdomains","resolutions","historical_whois","historical_urls","related_urls",
        "related_domains","related_ips","execution_parents","dropped_files","contacted_urls"
    }
    if relationship_type not in rel_enum:
        return _err("VALIDATION_ERROR", "relationship_type is invalid")
    if limit is None:
        limit = 40
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # URL normalization (service-defined)
    u = url.strip()
    try:
        p = urllib.parse.urlsplit(u)
    except Exception:
        return _err("VALIDATION_ERROR", "url cannot be parsed/normalized")
    if not p.scheme or not p.netloc:
        # try adding scheme if missing
        try:
            p = urllib.parse.urlsplit("http://" + u)
        except Exception:
            return _err("VALIDATION_ERROR", "url cannot be parsed/normalized")
    scheme = (p.scheme or "http").lower()
    host = p.hostname.lower() if p.hostname else ""
    if not host:
        return _err("VALIDATION_ERROR", "url cannot be normalized (missing host)")
    # punycode host
    try:
        host = host.encode("idna").decode("ascii")
    except Exception:
        return _err("VALIDATION_ERROR", "url host cannot be normalized")
    port = p.port
    default_port = (scheme == "http" and port in (None, 80)) or (scheme == "https" and port in (None, 443))
    netloc = host if default_port else f"{host}:{port}"
    path = p.path or "/"
    # drop fragment, keep query
    norm = urllib.parse.urlunsplit((scheme, netloc, path, p.query or "", ""))

    # compatibility validation for url observable type
    incompatible_for_url = {"execution_parents", "dropped_files", "historical_ssl_certificates", "historical_whois", "subdomains", "resolutions"}
    if relationship_type in incompatible_for_url:
        return _err("VALIDATION_ERROR", f"relationship_type '{relationship_type}' is not compatible with observable type 'url'")

    clients = _load("api_clients.json")
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        return _err("UNAUTHORIZED", "No active API client available to serve this request")
    client = sorted(active_clients, key=lambda c: c.get("created_at", ""))[0]
    client_id = client.get("id")

    # load logs and enforce quotas
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    todays = [r for r in logs if isinstance(r, dict) and r.get("client_id") == client_id and r.get("day") == day]
    used_requests = sum(1 for r in todays if r.get("upstream_requests", 0))
    used_rel_pages = sum(int(r.get("relationship_pages", 0) or 0) for r in todays)

    dq_req = client.get("daily_quota_requests")
    dq_rel = client.get("daily_quota_relationship_pages")
    if not isinstance(dq_req, int) or dq_req < 0:
        return _err("VALIDATION_ERROR", "Client daily_quota_requests is invalid")
    if not isinstance(dq_rel, int) or dq_rel < 0:
        return _err("VALIDATION_ERROR", "Client daily_quota_relationship_pages is invalid")

    # upsert url observable
    observables = _load("observables.json")
    if not isinstance(observables, list):
        observables = []
    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix+'|'+now_iso+'|'+os.urandom(8).hex()).encode()).hexdigest()[:24]}"
    obs = None
    for o in observables:
        if isinstance(o, dict) and o.get("type") == "url" and o.get("value") == norm:
            obs = o
            break
    if obs is None:
        obs = {
            "id": _new_id("obs"),
            "type": "url",
            "value": norm,
            "file_hash_kind": None,
            "url_normalization_version": 1,
            "first_seen_at": now_iso,
            "last_seen_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        observables.append(obs)
        _save("observables.json", observables)
    else:
        obs["last_seen_at"] = now_iso
        obs["updated_at"] = now_iso
        if obs.get("url_normalization_version") is None:
            obs["url_normalization_version"] = 1
        _save("observables.json", observables)

    from_observable_id = obs.get("id")

    relationships = _load("relationships.json")
    if not isinstance(relationships, list):
        relationships = []

    # cursor format: "rel:<relationship_type>:<offset>"
    offset = 0
    if cursor:
        parts = cursor.split(":")
        if len(parts) != 3 or parts[0] != "rel" or parts[1] != relationship_type or not parts[2].isdigit():
            logs.append({
                "id": f"log_{hashlib.sha256((endpoint+'|'+now_iso+'|badcursor').encode()).hexdigest()[:24]}",
                "timestamp": now_iso, "day": day, "endpoint": endpoint, "client_id": client_id,
                "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000),
                "upstream_requests": 0, "relationship_pages": 0
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "cursor is invalid for this relationship_type")
        offset = int(parts[2])

    cached = [e for e in relationships if isinstance(e, dict)
              and e.get("client_id") == client_id
              and e.get("from_observable_id") == from_observable_id
              and e.get("relationship_type") == relationship_type]
    cached.sort(key=lambda e: (e.get("fetched_at") or "", e.get("id") or ""))

    need_until = offset + limit
    upstream_used = 0
    rel_pages_used = 0
    if len(cached) < need_until:
        if used_rel_pages + 1 > dq_rel:
            logs.append({
                "id": f"log_{hashlib.sha256((endpoint+'|'+now_iso+'|relquota').encode()).hexdigest()[:24]}",
                "timestamp": now_iso, "day": day, "endpoint": endpoint, "client_id": client_id,
                "status": "QUOTA_EXCEEDED", "latency_ms": int((time.time()-t0)*1000),
                "upstream_requests": 0, "relationship_pages": 0
            })
            _save("request_logs.json", logs)
            return _err("QUOTA_EXCEEDED", "Daily relationship page quota exceeded", daily_quota_relationship_pages=dq_rel)
        if used_requests + 1 > dq_req:
            logs.append({
                "id": f"log_{hashlib.sha256((endpoint+'|'+now_iso+'|reqquota').encode()).hexdigest()[:24]}",
                "timestamp": now_iso, "day": day, "endpoint": endpoint, "client_id": client_id,
                "status": "QUOTA_EXCEEDED", "latency_ms": int((time.time()-t0)*1000),
                "upstream_requests": 0, "relationship_pages": 0
            })
            _save("request_logs.json", logs)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", daily_quota_requests=dq_req)

        upstream_used = 1
        rel_pages_used = 1

        seed = hashlib.sha256((client_id + "|" + norm + "|" + relationship_type).encode("utf-8")).hexdigest()
        page_index = len(cached) // 50
        vt_cursor = f"vt_{relationship_type}_{page_index}"

        for i in range(50):
            global_index = page_index * 50 + i
            h = hashlib.sha256((seed + "|" + str(global_index)).encode("utf-8")).hexdigest()
            to_type = None
            to_value = None
            ext_type = None
            ext_id = None
            display = None

            if relationship_type in ("communicating_files", "downloaded_files"):
                to_type = "file"; to_value = h[:64]; display = to_value
            elif relationship_type == "contacted_domains":
                to_type = "domain"; to_value = f"d{h[:10]}.example"; display = to_value
            elif relationship_type == "contacted_ips":
                a = int(h[0:2], 16); b = int(h[2:4], 16); c = int(h[4:6], 16); d = int(h[6:8], 16)
                to_type = "ip"; to_value = f"{a}.{b}.{c}.{d}"; display = to_value
            elif relationship_type in ("redirecting_urls", "redirected_urls", "related_urls", "contacted_urls"):
                to_type = "url"; to_value = f"https://u{h[:10]}.example/path"; display = to_value
            elif relationship_type == "related_threat_actors":
                ext_type = "threat_actor"; ext_id = f"ta_{h[:16]}"; display = f"Actor-{h[:6]}"
            elif relationship_type == "historical_urls":
                to_type = "url"; to_value = f"https://old{h[:8]}.example/"; display = to_value
            elif relationship_type in ("related_domains", "related_ips"):
                # For URLs, treat these as external (not compatible by VT in many cases); but allowed enum exists.
                # We model as observables to keep integrity.
                if relationship_type == "related_domains":
                    to_type = "domain"; to_value = f"rd{h[:10]}.example"; display = to_value
                else:
                    a = int(h[0:2], 16); b = int(h[2:4], 16); c = int(h[4:6], 16); d = int(h[6:8], 16)
                    to_type = "ip"; to_value = f"{a}.{b}.{c}.{d}"; display = to_value
            else:
                ext_type = "unknown"; ext_id = f"unk_{h[:20]}"; display = h[:12]

            to_observable_id = None
            if to_type is not None:
                o2 = None
                for oo in observables:
                    if isinstance(oo, dict) and oo.get("type") == to_type and oo.get("value") == to_value:
                        o2 = oo
                        break
                if o2 is None:
                    o2 = {
                        "id": _new_id("obs"),
                        "type": to_type,
                        "value": to_value,
                        "file_hash_kind": ("sha256" if to_type == "file" else None),
                        "url_normalization_version": (1 if to_type == "url" else None),
                        "first_seen_at": now_iso,
                        "last_seen_at": now_iso,
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    }
                    observables.append(o2)
                else:
                    o2["last_seen_at"] = now_iso
                    o2["updated_at"] = now_iso
                to_observable_id = o2.get("id")
                ext_type = "observable"
                ext_id = None

            uniq_key = (client_id, from_observable_id, relationship_type, to_observable_id or "", ext_id or "")
            exists = False
            for e in relationships:
                if not isinstance(e, dict):
                    continue
                k = (e.get("client_id"), e.get("from_observable_id"), e.get("relationship_type"),
                     e.get("to_observable_id") or "", e.get("to_external_id") or "")
                if k == uniq_key:
                    exists = True
                    break
            if exists:
                continue

            relationships.append({
                "id": _new_id("rel"),
                "client_id": client_id,
                "from_observable_id": from_observable_id,
                "relationship_type": relationship_type,
                "to_observable_id": to_observable_id,
                "to_external_type": ext_type,
                "to_external_id": (ext_id if to_observable_id is None else None),
                "to_display": display,
                "vt_cursor": vt_cursor,
                "fetched_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            })

        _save("observables.json", observables)
        _save("relationships.json", relationships)

        cached = [e for e in relationships if isinstance(e, dict)
                  and e.get("client_id") == client_id
                  and e.get("from_observable_id") == from_observable_id
                  and e.get("relationship_type") == relationship_type]
        cached.sort(key=lambda e: (e.get("fetched_at") or "", e.get("id") or ""))

    page = cached[offset: offset + limit]
    next_cursor = None
    if offset + len(page) < len(cached):
        next_cursor = f"rel:{relationship_type}:{offset+len(page)}"

    logs.append({
        "id": f"log_{hashlib.sha256((endpoint+'|'+now_iso+'|ok').encode()).hexdigest()[:24]}",
        "timestamp": now_iso,
        "day": day,
        "endpoint": endpoint,
        "client_id": client_id,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "upstream_requests": upstream_used,
        "relationship_pages": rel_pages_used,
    })
    _save("request_logs.json", logs)

    return {
        "data": {
            "from": {"type": "url", "value": norm, "normalization_version": 1},
            "relationship_type": relationship_type,
            "items": page,
            "limit": limit,
            "cursor": next_cursor,
            "meta": {"total_cached": len(cached), "returned": len(page), "has_more": next_cursor is not None},
        }
    }

def get_domain_relationship(client_id, domain, relationship_type, limit=None, cursor=None, refresh=None, **_extra):
    import json, os, datetime, time, re, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_domain_relationship"

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _day_key(dt):
        return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d")

    def _ensure_logs_list(x):
        return x if isinstance(x, list) else []

    def _log_request(cid, status, error_code=None):
        logs = _ensure_logs_list(_load("request_logs.json"))
        now = _utcnow()
        logs.append({
            "id": "vtc_req_" + hashlib.sha256(f"{endpoint}|{now.isoformat()}|{time.time_ns()}|{random.random()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "client_id": cid,
            "credential": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(now),
            "day": _day_key(now),
            "upstream_requests": 0,
            "relationship_pages": 0
        })
        _save("request_logs.json", logs)

    def _bump_last_log_field(cid, field, inc=1):
        logs = _ensure_logs_list(_load("request_logs.json"))
        for i in range(len(logs) - 1, -1, -1):
            r = logs[i]
            if isinstance(r, dict) and r.get("endpoint") == endpoint and r.get("client_id") == cid:
                r[field] = int(r.get(field, 0) or 0) + inc
                r["latency_ms"] = int((time.time() - t0) * 1000)
                logs[i] = r
                _save("request_logs.json", logs)
                return

    def _enforce_relationship_pages_quota(client_row, extra_pages):
        quota = client_row.get("daily_quota_relationship_pages")
        if not isinstance(quota, int) or quota < 0:
            return None
        logs = _ensure_logs_list(_load("request_logs.json"))
        today = _day_key(_utcnow())
        used = 0
        cid = client_row.get("id")
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != cid:
                continue
            if r.get("day") != today:
                continue
            used += int(r.get("relationship_pages", 0) or 0)
        if used + int(extra_pages) > quota:
            return _err("QUOTA_EXCEEDED", "Daily relationship page quota exceeded.", client_id=cid, daily_quota_relationship_pages=quota, used_relationship_pages=used, would_use=used + int(extra_pages))
        return None

    def _new_id(prefix):
        now = _utcnow()
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(f'{prefix}|{now.isoformat()}|{time.time_ns()}|{random.random()}'.encode('utf-8')).hexdigest()[:20]}"

    # validate
    if not isinstance(client_id, str) or not re.match(r"^vtc_cli_[0-9A-HJKMNP-TV-Z]{10,}$", client_id):
        _log_request(client_id if isinstance(client_id, str) else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "client_id must be a vtc_cli_ ULID.", client_id=client_id)
    if not isinstance(domain, str) or not domain.strip():
        _log_request(client_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "domain must be a non-empty string.")
    domain_val = domain.strip().lower().strip(".")
    allowed = {
        "historical_ssl_certificates",
        "subdomains",
        "resolutions",
        "historical_whois",
        "historical_urls",
        "related_urls",
        "related_domains",
        "related_ips",
        "related_threat_actors"
    }
    if relationship_type not in allowed:
        _log_request(client_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "relationship_type is not valid for domain.", allowed=list(sorted(allowed)))
    if limit is None:
        limit = 40
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_request(client_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        _log_request(client_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        _log_request(client_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "refresh must be a boolean")

    # resolve client by id, must be active
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    client = next((c for c in clients if isinstance(c, dict) and c.get("id") == client_id), None)
    if not client:
        _log_request(client_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "API client not found.", client_id=client_id)
    if client.get("status") != "active":
        _log_request(client_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API client is not active.", client_id=client_id, status=client.get("status"))

    _log_request(client_id, "ok")

    # upsert domain observable
    now = _utcnow()
    obs = _load("observables.json")
    if not isinstance(obs, list):
        obs = []
    observable = None
    for row in obs:
        if isinstance(row, dict) and row.get("type") == "domain" and row.get("value") == domain_val:
            observable = row
            break
    if observable is None:
        observable = {
            "id": _new_id("vtc_obs"),
            "type": "domain",
            "value": domain_val,
            "file_hash_kind": None,
            "url_normalization_version": None,
            "first_seen_at": _iso(now),
            "last_seen_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now)
        }
        obs.append(observable)
        _save("observables.json", obs)
    else:
        observable["last_seen_at"] = _iso(now)
        observable["updated_at"] = _iso(now)
        if not observable.get("first_seen_at"):
            observable["first_seen_at"] = _iso(now)
        for i in range(len(obs)):
            if isinstance(obs[i], dict) and obs[i].get("id") == observable.get("id"):
                obs[i] = observable
                break
        _save("observables.json", obs)

    rels = _load("relationships.json")
    if not isinstance(rels, list):
        rels = []

    # If refresh requested: enforce relationship page quota and mark usage, but do not fail due to "offline".
    if refresh:
        qerr = _enforce_relationship_pages_quota(client, 1)
        if qerr:
            _log_request(client_id, "error", "QUOTA_EXCEEDED")
            return qerr
        _bump_last_log_field(client_id, "relationship_pages", 1)
        # No upstream available; best-effort behavior is to return cached page (possibly empty).

    candidates = [r for r in rels if isinstance(r, dict) and r.get("client_id") == client_id and r.get("from_observable_id") == observable["id"] and r.get("relationship_type") == relationship_type]
    page_cursor = cursor
    if page_cursor is None:
        page_none = [r for r in candidates if r.get("vt_cursor") in (None, "")]
        if page_none:
            page_cursor = None
        else:
            cursors = sorted({r.get("vt_cursor") for r in candidates if isinstance(r.get("vt_cursor"), str) and r.get("vt_cursor")})
            page_cursor = cursors[0] if cursors else None
    page_rows = [r for r in candidates if (r.get("vt_cursor") or None) == (page_cursor or None)]

    items = []
    for r in page_rows[:limit]:
        items.append({
            "id": r.get("id"),
            "relationship_type": r.get("relationship_type"),
            "to_observable_id": r.get("to_observable_id"),
            "to_external_type": r.get("to_external_type"),
            "to_external_id": r.get("to_external_id"),
            "to_display": r.get("to_display"),
            "fetched_at": r.get("fetched_at"),
            "vt_cursor": r.get("vt_cursor")
        })

    all_cursors = sorted({r.get("vt_cursor") for r in candidates if isinstance(r.get("vt_cursor"), str) and r.get("vt_cursor")})
    next_cursor = None
    if page_cursor is None:
        next_cursor = all_cursors[0] if all_cursors else None
    else:
        if page_cursor in all_cursors:
            idx = all_cursors.index(page_cursor)
            if idx + 1 < len(all_cursors):
                next_cursor = all_cursors[idx + 1]

    return {
        "client_id": client_id,
        "from_observable_id": observable["id"],
        "relationship_type": relationship_type,
        "cursor": page_cursor,
        "items": items,
        "limit": limit,
        "has_more": bool(next_cursor),
        "next_cursor": next_cursor,
        "total_cached_for_cursor": len(page_rows),
        "total_cached_all_pages": len(candidates),
        "refreshed": bool(refresh)
    }

