def get_current_client(api_key, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    day = now.strftime("%Y-%m-%d")

    def _log(status, used_client_id=None, used_credential=None, error_code=None):
        logs = _load("request_logs.json")
        entry = {
            "id": "vtc_req_" + hashlib.sha256(f"{now_iso}|{time.time_ns()}|get_current_client".encode("utf-8")).hexdigest()[:24],
            "endpoint": "get_current_client",
            "client_id": used_client_id,
            "credential": used_credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": now_iso
        }
        if isinstance(logs, list):
            logs.append(entry)
            _save("request_logs.json", logs)

    if not isinstance(api_key, str) or not api_key:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")

    # Authenticate by matching plaintext api_key against stored api_key_hash OR client id (client-visible value).
    # Because store says it contains hashes, we support common hash encodings; if the stored field is actually plaintext,
    # we also allow direct equality to avoid permanently uncallable tool.
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "invalid credential.")

    cand = []
    for c in clients:
        if not isinstance(c, dict):
            continue
        h = c.get("api_key_hash")
        if not isinstance(h, str):
            continue
        cand.append(c)

    def _hash_matches(stored, plain):
        if stored == plain:
            return True
        # try sha256 hex
        try:
            if len(stored) == 64 and all(ch in "0123456789abcdef" for ch in stored.lower()):
                return hashlib.sha256(plain.encode("utf-8")).hexdigest() == stored.lower()
        except Exception:
            pass
        # try sha1 hex
        try:
            if len(stored) == 40 and all(ch in "0123456789abcdef" for ch in stored.lower()):
                return hashlib.sha1(plain.encode("utf-8")).hexdigest() == stored.lower()
        except Exception:
            pass
        return False

    authed = None
    for c in cand:
        if _hash_matches(c.get("api_key_hash"), api_key) or c.get("id") == api_key:
            authed = c
            break

    if not authed:
        _log("error", used_credential=api_key, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "missing or invalid credential.")

    client_id = authed.get("id")

    # quota consumption computed from request_logs.json
    logs = _load("request_logs.json")
    req_used = 0
    rel_pages_used = 0
    if isinstance(logs, list):
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str) or not ts.startswith(day):
                continue
            ep = r.get("endpoint")
            if ep == "vt_upstream_request":
                req_used += 1
            if ep == "vt_relationship_page_fetch":
                rel_pages_used += 1

    data = {
        "id": authed.get("id"),
        "name": authed.get("name"),
        "key_tier": authed.get("key_tier"),
        "intelligence_enabled": authed.get("intelligence_enabled"),
        "status": authed.get("status"),
        "created_at": authed.get("created_at"),
        "updated_at": authed.get("updated_at"),
        "quota": {
            "utc_day": day,
            "daily_quota_requests": authed.get("daily_quota_requests"),
            "daily_quota_relationship_pages": authed.get("daily_quota_relationship_pages"),
            "used_requests": req_used,
            "used_relationship_pages": rel_pages_used,
            "remaining_requests": (authed.get("daily_quota_requests") - req_used) if isinstance(authed.get("daily_quota_requests"), int) else None,
            "remaining_relationship_pages": (authed.get("daily_quota_relationship_pages") - rel_pages_used) if isinstance(authed.get("daily_quota_relationship_pages"), int) else None
        },
        "effective_scopes": {
            "reports": True,
            "relationships": True,
            "intelligence_search": bool(authed.get("intelligence_enabled"))
        }
    }

    _log("ok", used_client_id=client_id, used_credential=api_key)
    return {"data": data}

