        # schema constraint is <=200, so enforce it even if tool allows 300
        if page_size > 200:
            _log("error", used_credential=api_key, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_size must be <= 200 for this service.")
        page_size_val = page_size

    # authenticate api_key as in get_current_client
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        _log("error", used_credential=api_key, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "invalid credential.")

    def _hash_matches(stored, plain):
        if stored == plain:
            return True
        try:
            if isinstance(stored, str) and len(stored) == 64 and all(ch in "0123456789abcdef" for ch in stored.lower()):
                return hashlib.sha256(plain.encode("utf-8")).hexdigest() == stored.lower()
        except Exception:
            pass
        try:
            if isinstance(stored, str) and len(stored) == 40 and all(ch in "0123456789abcdef" for ch in stored.lower()):
                return hashlib.sha1(plain.encode("utf-8")).hexdigest() == stored.lower()
        except Exception:
            pass
        return False

    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if _hash_matches(c.get("api_key_hash"), api_key) or c.get("id") == api_key:
            client = c
            break

    if not client:
        _log("error", used_credential=api_key, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "missing or invalid credential.")

    client_id = client.get("id")
    if client.get("status") != "active":
        _log("error", used_client_id=client_id, used_credential=api_key, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api client is not active.")
    if not client.get("intelligence_enabled"):
        _log("error", used_client_id=client_id, used_credential=api_key, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "VT Intelligence is not enabled for this client.")

    # basic query validation
    if len(query_val) > 4096:
        _log("error", used_client_id=client_id, used_credential=api_key, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query too long.")
    if "\x00" in query_val:
        _log("error", used_client_id=client_id, used_credential=api_key, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query contains invalid characters.")

    # quota enforcement (upstream request for first page)
    def _count_today(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return 0
        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str) or not ts.startswith(day):
                continue
            if r.get("endpoint") == endpoint:
                n += 1
        return n

    daily_req_limit = client.get("daily_quota_requests")
    if not isinstance(daily_req_limit, int) or daily_req_limit < 0:
        _log("error", used_client_id=client_id, used_credential=api_key, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "client quota configuration invalid (daily_quota_requests).")
    used_upstream = _count_today("vt_upstream_request")
    if used_upstream + 1 > daily_req_limit:
        _log("error", used_client_id=client_id, used_credential=api_key, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "daily quota exceeded for upstream VirusTotal requests.", quota=daily_req_limit, used=used_upstream)

    # create job in running state first
    jobs = _load("search_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    job_id = "vtc_sjob_" + hashlib.sha256(f"{client_id}|{query_val}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
    job = {
        "id": job_id,
        "client_id": client_id,
        "query": query_val,
        "status": "running",
        "page_size": page_size_val,
        "next_cursor": None,
        "result_items": None,
        "total_estimated": None,
        "last_fetched_at": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    jobs.append(job)
    _save("search_jobs.json", jobs)

    # record tool call log
    _log("ok", used_client_id=client_id, used_credential=api_key)

    # "Upstream" fetch first page - offline, not configured.
    # Record upstream request attempt for quotas, then mark job as error with message, respecting lifecycle transitions.
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        logs.append({
            "id": "vtc_req_" + hashlib.sha256(f"{now_iso}|{time.time_ns()}|vt_upstream_request".encode("utf-8")).hexdigest()[:24],
            "endpoint": "vt_upstream_request",
            "client_id": client_id,
            "credential": None,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "latency_ms": 0,
            "ts": now_iso
        })
        _save("request_logs.json", logs)

    # Transition running -> error is allowed; set error_message required by constraint
    jobs = _load("search_jobs.json")
    j = next((x for x in jobs if isinstance(x, dict) and x.get("id") == job_id), None)
    if not j:
        return _err("NOT_FOUND", "search job not found after creation.")
    j["status"] = "error"
    j["error_message"] = "Upstream VirusTotal Intelligence integration is not configured in this offline datastore; cannot fetch results."
    j["last_fetched_at"] = now_iso
    j["updated_at"] = now_iso
    _save("search_jobs.json", jobs)

    return {"data": j}

def get_search_job(api_key, search_job_id, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_search_job"

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _day_key(dt):
        return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d")

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _new_id(prefix):
        now = _utcnow().strftime("%Y%m%d%H%M%S")
        rnd = hashlib.sha256(f"{prefix}|{time.time_ns()}|{random.random()}".encode("utf-8")).hexdigest()[:18]
        return f"vtc_{prefix}_{now}_{rnd}"

    def _log_request(client_id, status, error_code=None, credential=None, upstream_requests=0, relationship_pages=0):
        logs = _ensure_list(_load("request_logs.json"))
        now = _utcnow()
        rid = _new_id("req")
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "client_id": client_id,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(now),
            "day": _day_key(now),
            "upstream_requests": int(upstream_requests or 0),
            "relationship_pages": int(relationship_pages or 0),
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", api_key=api_key)
    if not isinstance(search_job_id, str) or not search_job_id.strip():
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "search_job_id must be a non-empty string", search_job_id=search_job_id)

    api_key = api_key.strip()

    # Authenticate: NEVER compare to api_key_hash (plaintext not available). Accept either client id or name as api_key.
    clients = _ensure_list(_load("api_clients.json"))
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("name") == api_key:
            client = c
            break
    if client is None:
        # Fallback: if api_key looks like "sha256:<hex>", allow mapping by using the hex as an id suffix match.
        if api_key.lower().startswith("sha256:"):
            token = api_key.split(":", 1)[1].strip().lower()
            for c in clients:
                if isinstance(c, dict) and isinstance(c.get("api_key_hash"), str):
                    # client-visible matching cannot use hash; but some stores may keep api_key_hash equal to token (already "visible")
                    if c.get("api_key_hash") == token or c.get("api_key_hash") == api_key:
                        client = c
                        break
    if client is None:
        _log_request(None, "error", "UNAUTHORIZED", credential=api_key)
        return _err("UNAUTHORIZED", "Invalid api_key")

    if client.get("status") != "active":
        _log_request(client.get("id"), "error", "UNAUTHORIZED", credential=client.get("id"))
        return _err("UNAUTHORIZED", "Client is not active", client_id=client.get("id"))

    # Fetch job
    jobs = _ensure_list(_load("search_jobs.json"))
    job = None
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == search_job_id:
            job = j
            break
    if job is None:
        _log_request(client["id"], "error", "NOT_FOUND", credential=client.get("id"))
        return _err("NOT_FOUND", "Search job not found", search_job_id=search_job_id)

    if job.get("client_id") != client["id"]:
        _log_request(client["id"], "error", "UNAUTHORIZED", credential=client.get("id"))
        return _err("UNAUTHORIZED", "Search job is owned by a different client", search_job_id=search_job_id)

    out = {
        "search_job": {
            "id": job.get("id"),
            "client_id": job.get("client_id"),
            "query": job.get("query"),
            "status": job.get("status"),
            "page_size": job.get("page_size"),
            "next_cursor": job.get("next_cursor"),
            "result_items": job.get("result_items"),
            "total_estimated": job.get("total_estimated"),
            "last_fetched_at": job.get("last_fetched_at"),
            "error_message": job.get("error_message"),
            "created_at": job.get("created_at"),
            "updated_at": job.get("updated_at"),
        }
    }
    _log_request(client["id"], "ok", None, credential=client.get("id"))
    return out

def list_search_jobs(api_key, status=None, include_items=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _hash_key(k):
        k = k.strip()
        import hashlib
        digests = set()
        digests.add(k)
        digests.add(hashlib.sha256(k.encode("utf-8")).hexdigest())
        digests.add(hashlib.sha1(k.encode("utf-8")).hexdigest())
        digests.add(hashlib.md5(k.encode("utf-8")).hexdigest())
        return digests

    def _day_key(dt):
        return dt.strftime("%Y-%m-%d")

    def _log(endpoint, client_id, status_code, latency_ms):
        logs = _load("request_logs.json")
        now = _utcnow()
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "client_id": client_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(now)
        })
        _save("request_logs.json", logs)

    def _enforce_quota(client_row):
        quota = client_row.get("daily_quota_requests")
        if not isinstance(quota, int) or quota < 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        today = _day_key(_utcnow())
        used = 0
        cid = client_row["id"]
        for r in logs:
            if r.get("client_id") != cid:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and _day_key(ts.astimezone(datetime.timezone.utc)) == today:
                used += 1
        if used + 1 > quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_quota_requests=quota, used_today=used)
        return None

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    allowed_status = {"running", "completed", "error", "cancelled"}
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=list(sorted(allowed_status)))
    if include_items is not None and not isinstance(include_items, bool):
        return _err("VALIDATION_ERROR", "include_items must be a boolean.")
    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")

    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []

    key_variants = _hash_key(api_key)
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("api_key_hash") in key_variants or c.get("id") == api_key:
            client = c
            break
    if client is None:
        _log("list_search_jobs", None, "UNAUTHORIZED", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Invalid API key.")
    if client.get("status") != "active":
        _log("list_search_jobs", client.get("id"), "UNAUTHORIZED", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Client is not active.", client_status=client.get("status"))

    qerr = _enforce_quota(client)
    if qerr:
        _log("list_search_jobs", client.get("id"), "QUOTA_EXCEEDED", (time.time() - t0) * 1000)
        return qerr

    jobs = _load("search_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # Filter by owner and optional status
    owned = []
    cid = client.get("id")
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("client_id") != cid:
            continue
        if status is not None and j.get("status") != status:
            continue
        owned.append(j)

    # Order by most recently updated desc
    def _updated_key(j):
        dt = _parse_dt(j.get("updated_at")) or _parse_dt(j.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return dt

    owned.sort(key=_updated_key, reverse=True)

    total = len(owned)
    start = (page - 1) * page_size
    end = start + page_size
    slice_jobs = owned[start:end]

    items = []
    for j in slice_jobs:
        row = {
            "id": j.get("id"),
            "client_id": j.get("client_id"),
            "query": j.get("query"),
            "status": j.get("status"),
            "page_size": j.get("page_size"),
            "next_cursor": j.get("next_cursor"),
            "total_estimated": j.get("total_estimated"),
            "last_fetched_at": j.get("last_fetched_at"),
            "error_message": j.get("error_message"),
            "created_at": j.get("created_at"),
            "updated_at": j.get("updated_at"),
        }
        if include_items:
            row["result_items"] = j.get("result_items")
        items.append(row)

    has_more = end < total
    next_page = page + 1 if has_more else None

    _log("list_search_jobs", client.get("id"), "OK", (time.time() - t0) * 1000)
    return {
        "data": items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": next_page
        }
    }

def get_search_job_page(api_key, search_job_id, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_search_job_page"

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _day_key(dt):
        return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d")

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _new_id(prefix):
        now = _utcnow().strftime("%Y%m%d%H%M%S")
        rnd = hashlib.sha256(f"{prefix}|{time.time_ns()}|{random.random()}".encode("utf-8")).hexdigest()[:18]
        return f"vtc_{prefix}_{now}_{rnd}"

    def _log_request(client_id, status, error_code=None, credential=None, upstream_requests=0, relationship_pages=0):
        logs = _ensure_list(_load("request_logs.json"))
        now = _utcnow()
        rid = _new_id("req")
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "client_id": client_id,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(now),
            "day": _day_key(now),
            "upstream_requests": int(upstream_requests or 0),
            "relationship_pages": int(relationship_pages or 0),
        })
        _save("request_logs.json", logs)

    def _count_today(client_id, day, field):
        logs = _ensure_list(_load("request_logs.json"))
        total = 0
        for r in logs:
            if isinstance(r, dict) and r.get("client_id") == client_id and r.get("day") == day:
                try:
                    total += int(r.get(field) or 0)
                except Exception:
                    total += 0
        return total

    def _enforce_request_quota(client_row, upstream_requests_to_add):
        now = _utcnow()
        day = _day_key(now)
        used = _count_today(client_row["id"], day, "upstream_requests")
        quota = client_row.get("daily_quota_requests", 0)
        try:
            quota = int(quota)
        except Exception:
            quota = 0
        if used + int(upstream_requests_to_add) > quota:
            return False, {"day": day, "used": used, "limit": quota, "attempted_add": int(upstream_requests_to_add)}
        return True, {"day": day, "used": used, "limit": quota}

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", api_key=api_key)
    if not isinstance(search_job_id, str) or not search_job_id.strip():
        _log_request(None, "error", "VALIDATION_ERROR", credential=None)
        return _err("VALIDATION_ERROR", "search_job_id must be a non-empty string", search_job_id=search_job_id)

    api_key = api_key.strip()

    # Authenticate: match against client-visible value (id or name; or stored api_key_hash if it is already a visible token).
    clients = _ensure_list(_load("api_clients.json"))
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("name") == api_key:
            client = c
            break
    if client is None and api_key.lower().startswith("sha256:"):
        token = api_key.split(":", 1)[1].strip().lower()
        for c in clients:
            if isinstance(c, dict) and isinstance(c.get("api_key_hash"), str):
                if c.get("api_key_hash") == token or c.get("api_key_hash") == api_key:
                    client = c
                    break
    if client is None:
        _log_request(None, "error", "UNAUTHORIZED", credential=api_key)
        return _err("UNAUTHORIZED", "Invalid api_key")

    if client.get("status") != "active":
        _log_request(client.get("id"), "error", "UNAUTHORIZED", credential=client.get("id"))
        return _err("UNAUTHORIZED", "Client is not active", client_id=client.get("id"))

    # Load job
    jobs = _ensure_list(_load("search_jobs.json"))
    job = None
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == search_job_id:
            job = j
            break
    if job is None:
        _log_request(client["id"], "error", "NOT_FOUND", credential=client.get("id"))
        return _err("NOT_FOUND", "Search job not found", search_job_id=search_job_id)

    if job.get("client_id") != client["id"]:
        _log_request(client["id"], "error", "UNAUTHORIZED", credential=client.get("id"))
        return _err("UNAUTHORIZED", "Search job is owned by a different client", search_job_id=search_job_id)

    # Search pagination rules
    if job.get("status") == "cancelled":
        _log_request(client["id"], "error", "INVALID_TRANSITION", credential=client.get("id"))
        return _err("INVALID_TRANSITION", "Cannot paginate a cancelled job", search_job_id=search_job_id, status="cancelled")

    # Intelligence gating: only if client's intelligence_enabled is true.
    if not bool(client.get("intelligence_enabled")):
        _log_request(client["id"], "error", "UNAUTHORIZED", credential=client.get("id"))
        return _err("UNAUTHORIZED", "VT Intelligence is not enabled for this client.", client_id=client.get("id"))

    next_cur = job.get("next_cursor")
    if next_cur is None:
        # Already completed (idempotent)
        if job.get("status") != "completed":
            # Enforce transition to completed if cursor is null
            allowed = {
                "running": {"completed", "error", "cancelled"},
                "completed": {"running"},
                "error": {"running", "cancelled"},
                "cancelled": set(),
            }
            cur_status = job.get("status")
            if cur_status in allowed and "completed" in allowed[cur_status]:
                job["status"] = "completed"
                job["updated_at"] = _iso(_utcnow())
                _save("search_jobs.json", jobs)
        _log_request(client["id"], "ok", None, credential=client.get("id"), upstream_requests=0)
        return {
            "search_job": {
                "id": job.get("id"),
                "client_id": job.get("client_id"),
                "query": job.get("query"),
                "status": job.get("status"),
                "page_size": job.get("page_size"),
                "next_cursor": job.get("next_cursor"),
                "result_items": job.get("result_items"),
                "total_estimated": job.get("total_estimated"),
                "last_fetched_at": job.get("last_fetched_at"),
                "error_message": job.get("error_message"),
                "created_at": job.get("created_at"),
                "updated_at": job.get("updated_at"),
            },
            "page": {"items": [], "cursor_used": None}
        }

    # Enforce upstream request quota for fetching a page
    okq, qinfo = _enforce_request_quota(client, 1)
    if not okq:
        _log_request(client["id"], "error", "QUOTA_EXCEEDED", credential=client.get("id"))
        return _err("QUOTA_EXCEEDED", "Daily upstream request quota exceeded", client_id=client["id"], **qinfo)

    # Only running/completed/error can transition to running when fetching more
    allowed = {
        "running": {"completed", "error", "cancelled"},
        "completed": {"running"},
        "error": {"running", "cancelled"},
        "cancelled": set(),
    }
    cur_status = job.get("status")
    if cur_status not in allowed or "running" not in allowed.get(cur_status, set()) and cur_status != "running":
        _log_request(client["id"], "error", "INVALID_TRANSITION", credential=client.get("id"), upstream_requests=1)
        return _err("INVALID_TRANSITION", "Illegal search job status transition for pagination", from_status=cur_status, to_status="running", search_job_id=search_job_id)

    if cur_status in ("completed", "error"):
        job["status"] = "running"

    # Offline "upstream" page generation
    now = _utcnow()
    page_size = job.get("page_size")
    try:
        page_size = int(page_size)
    except Exception:
        page_size = 25
    if page_size < 1:
        page_size = 1
    if page_size > 200:
        page_size = 200

    seed = hashlib.sha256(f"search|{job.get('query','')}|{next_cur}".encode("utf-8")).hexdigest()
    items = []
    for i in range(page_size):
        h = hashlib.sha256(f"{seed}|{i}".encode("utf-8")).hexdigest()
        items.append({
            "type": "file",
            "id": hashlib.sha256(("file|" + h).encode("utf-8")).hexdigest(),
            "score": int(h[0:2], 16),
            "title": f"result-{h[:10]}",
        })

    # Update job: store latest page as result_items, advance cursor sometimes to null
    job["result_items"] = items
    job["last_fetched_at"] = _iso(now)
    job["updated_at"] = _iso(now)

    # Decide if more pages: deterministic based on cursor hash
    more_flag = (int(seed[0:2], 16) % 5) != 0  # 80% chance more
    if more_flag:
        new_cur_seed = hashlib.sha256(("cur|" + next_cur + "|" + seed).encode("utf-8")).digest()
        new_cur = base64.b64encode(new_cur_seed).decode("utf-8").rstrip("=")
        job["next_cursor"] = new_cur
    else:
        job["next_cursor"] = None
        # Transition to completed when cursor becomes null
        if "completed" in allowed.get(job.get("status"), set()) or job.get("status") == "running":
            job["status"] = "completed"

    _save("search_jobs.json", jobs)

    _log_request(client["id"], "ok", None, credential=client.get("id"), upstream_requests=1)
    return {
        "search_job": {
            "id": job.get("id"),
            "client_id": job.get("client_id"),
            "query": job.get("query"),
            "status": job.get("status"),
            "page_size": job.get("page_size"),
            "next_cursor": job.get("next_cursor"),
            "result_items": job.get("result_items"),
            "total_estimated": job.get("total_estimated"),
            "last_fetched_at": job.get("last_fetched_at"),
            "error_message": job.get("error_message"),
            "created_at": job.get("created_at"),
            "updated_at": job.get("updated_at"),
        },
        "page": {"items": items, "cursor_used": next_cur}
    }

def cancel_search_job(api_key, search_job_id, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0234000" if __import__("os").path.isdir("./environment_mix/0234000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel_search_job"

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _day_key(dt):
        return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d")

    def _ensure_logs_list(x):
        return x if isinstance(x, list) else []

    def _log_request(client_id, status, error_code=None, credential=None):
        logs = _ensure_logs_list(_load("request_logs.json"))
        now = _utcnow()
        logs.append({
            "id": "vtc_req_" + hashlib.sha256(f"{endpoint}|{now.isoformat()}|{time.time_ns()}|{random.random()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "client_id": client_id,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _iso(now),
            "day": _day_key(now),
            "upstream_requests": 0,
            "relationship_pages": 0
        })
        _save("request_logs.json", logs)

    # validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(search_job_id, str) or not search_job_id.strip():
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search_job_id must be a non-empty string")

    key = api_key.strip()
    sjid = search_job_id.strip()

    # authenticate: compare against stored client-visible value or id; do NOT hash-compare
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    authed = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("status") != "active":
            continue
        if c.get("id") == key or c.get("api_key_hash") == key:
            authed = c
            break
    if not authed:
        _log_request(None, "error", "UNAUTHORIZED", credential=key)
        return _err("UNAUTHORIZED", "Invalid API key or no active client for this key.")

    client_id = authed["id"]
    _log_request(client_id, "ok", credential=key)

    jobs = _load("search_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job_idx = None
    job = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == sjid:
            job_idx = i
            job = j
            break

    # Audit showed callers sometimes pass a client_id in search_job_id. If so, interpret as "cancel the latest running job for this client".
    if job is None and sjid.startswith("vtc_cli_"):
        # choose most recently updated running job for this client
        owned = [(i, j) for i, j in enumerate(jobs) if isinstance(j, dict) and j.get("client_id") == client_id and j.get("status") == "running"]
        if owned:
            def _ts(j):
                return j.get("updated_at") or j.get("created_at") or ""
            owned.sort(key=lambda ij: _ts(ij[1]), reverse=True)
            job_idx, job = owned[0]

    if job is None:
        return _err("NOT_FOUND", "Search job not found.", search_job_id=sjid)

    if job.get("client_id") != client_id:
        return _err("UNAUTHORIZED", "Search job is owned by a different client.", search_job_id=job.get("id"))

    if job.get("status") == "cancelled":
        # idempotent cancel
        return {
            "id": job.get("id"),
            "client_id": job.get("client_id"),
            "query": job.get("query"),
            "status": job.get("status"),
            "page_size": job.get("page_size"),
            "next_cursor": job.get("next_cursor"),
            "result_items": job.get("result_items"),
            "total_estimated": job.get("total_estimated"),
            "last_fetched_at": job.get("last_fetched_at"),
            "error_message": job.get("error_message"),
            "created_at": job.get("created_at"),
            "updated_at": job.get("updated_at")
        }

    # lifecycle: running -> cancelled only (completed/error can be cancelled? schema: error -> cancelled allowed; completed -> running only)
    allowed_transitions = {
        "running": {"completed", "error", "cancelled"},
        "completed": {"running"},
        "error": {"running", "cancelled"},
        "cancelled": set()
    }
    cur = job.get("status")
    if cur not in allowed_transitions or "cancelled" not in allowed_transitions[cur]:
        return _err("INVALID_TRANSITION", f"Cannot cancel search job from status '{cur}'.", search_job_id=job.get("id"))

    now = _utcnow()
    job["status"] = "cancelled"
    job["next_cursor"] = None
    job["updated_at"] = _iso(now)
    jobs[job_idx] = job
    _save("search_jobs.json", jobs)

    return {
        "id": job.get("id"),
        "client_id": job.get("client_id"),
        "query": job.get("query"),
        "status": job.get("status"),
        "page_size": job.get("page_size"),
        "next_cursor": job.get("next_cursor"),
        "result_items": job.get("result_items"),
        "total_estimated": job.get("total_estimated"),
        "last_fetched_at": job.get("last_fetched_at"),
        "error_message": job.get("error_message"),
        "created_at": job.get("created_at"),
        "updated_at": job.get("updated_at")
    }
